{"status":"RTL_GENERATED","task_type":"INITIAL_GENERATION","summary":"Implemented all frozen manifest modules for gemm_bias_relu_npu v1.0 as synthesizable SystemVerilog with synchronous active-low reset, FSM-controlled load/compute/emit flow, strict ready/valid handling, int8xint8->int16->int32 accumulation, optional bias add, ReLU, and row-major output ordering.","files":[{"path":"gemm_bias_relu_npu_top.sv","module":"gemm_bias_relu_npu_top","purpose":"Top integration, interface handling, buffer storage, and submodule wiring.","content":"module gemm_bias_relu_npu_top #(
  parameter int MAX_M = 64,
  parameter int MAX_N = 64,
  parameter int MAX_K = 64,
  parameter int TILE_N = 8
) (
  input  logic                     clk,
  input  logic                     rst_n,
  input  logic                     cmd_valid,
  output logic                     cmd_ready,
  input  logic [95:0]              cmd_data,
  input  logic                     a_valid,
  output logic                     a_ready,
  input  logic signed [7:0]        a_data,
  input  logic                     b_valid,
  output logic                     b_ready,
  input  logic signed [7:0]        b_data,
  input  logic                     bias_valid,
  output logic                     bias_ready,
  input  logic signed [31:0]       bias_data,
  output logic                     out_valid,
  input  logic                     out_ready,
  output logic signed [31:0]       out_data,
  output logic                     status_done,
  output logic                     status_error
);
  localparam int A_DEPTH = MAX_M*MAX_K;
  localparam int B_DEPTH = MAX_K*MAX_N;

  logic [15:0] cfg_m, cfg_n, cfg_k;
  logic        cfg_bias_enable;

  logic st_load_a, st_load_b, st_load_bias, st_compute, st_emit;
  logic do_compute_start, do_compute_step, do_emit_start, do_done_pulse;

  logic load_a_done, load_b_done, load_bias_done;

  logic [$clog2(A_DEPTH)-1:0] a_wr_addr;
  logic [$clog2(B_DEPTH)-1:0] b_wr_addr;
  logic [$clog2(MAX_N)-1:0]   bias_wr_addr;
  logic                       a_wr_en, b_wr_en, bias_wr_en;

  logic signed [7:0]   buf_A [0:A_DEPTH-1];
  logic signed [7:0]   buf_B [0:B_DEPTH-1];
  logic signed [31:0]  buf_bias [0:MAX_N-1];

  logic [$clog2(MAX_M)-1:0] idx_m;
  logic [$clog2(MAX_N)-1:0] idx_n_base;
  logic [$clog2(MAX_K)-1:0] idx_k;
  logic [TILE_N-1:0]        lane_active;

  logic signed [7:0] a_elem;
  logic signed [7:0] b_vec [0:TILE_N-1];

  logic compute_tile_done;
  logic signed [31:0] lane_acc [0:TILE_N-1];

  logic signed [31:0] lane_post [0:TILE_N-1];

  logic emit_busy;
  logic emit_done;

  npu_control_fsm #(.MAX_M(MAX_M), .MAX_N(MAX_N), .MAX_K(MAX_K), .TILE_N(TILE_N)) u_ctrl (
    .clk(clk), .rst_n(rst_n), .cmd_valid(cmd_valid), .cmd_ready(cmd_ready), .cmd_data(cmd_data),
    .load_a_done(load_a_done), .load_b_done(load_b_done), .load_bias_done(load_bias_done),
    .compute_tile_done(compute_tile_done), .emit_done(emit_done),
    .cfg_m(cfg_m), .cfg_n(cfg_n), .cfg_k(cfg_k), .cfg_bias_enable(cfg_bias_enable),
    .st_load_a(st_load_a), .st_load_b(st_load_b), .st_load_bias(st_load_bias), .st_compute(st_compute), .st_emit(st_emit),
    .do_compute_start(do_compute_start), .do_compute_step(do_compute_step), .do_emit_start(do_emit_start), .do_done_pulse(do_done_pulse),
    .idx_m(idx_m), .idx_n_base(idx_n_base), .idx_k(idx_k), .lane_active(lane_active),
    .status_error(status_error)
  );

  input_loader #(.MAX_M(MAX_M), .MAX_N(MAX_N), .MAX_K(MAX_K)) u_loader (
    .clk(clk), .rst_n(rst_n), .st_load_a(st_load_a), .st_load_b(st_load_b), .st_load_bias(st_load_bias), .bias_enable(cfg_bias_enable),
    .cfg_m(cfg_m), .cfg_n(cfg_n), .cfg_k(cfg_k),
    .a_valid(a_valid), .a_ready(a_ready), .a_data(a_data),
    .b_valid(b_valid), .b_ready(b_ready), .b_data(b_data),
    .bias_valid(bias_valid), .bias_ready(bias_ready), .bias_data(bias_data),
    .a_wr_en(a_wr_en), .a_wr_addr(a_wr_addr), .a_wr_data(),
    .b_wr_en(b_wr_en), .b_wr_addr(b_wr_addr), .b_wr_data(),
    .bias_wr_en(bias_wr_en), .bias_wr_addr(bias_wr_addr), .bias_wr_data(),
    .load_a_done(load_a_done), .load_b_done(load_b_done), .load_bias_done(load_bias_done)
  );

  always_ff @(posedge clk) begin
    if (a_wr_en) buf_A[a_wr_addr] <= a_data;
    if (b_wr_en) buf_B[b_wr_addr] <= b_data;
    if (bias_wr_en) buf_bias[bias_wr_addr] <= bias_data;
  end

  always_comb begin
    int n_idx;
    a_elem = buf_A[(idx_m*cfg_k)+idx_k];
    for (int i = 0; i < TILE_N; i++) begin
      n_idx = idx_n_base + i;
      if (lane_active[i]) b_vec[i] = buf_B[(idx_k*cfg_n)+n_idx];
      else                b_vec[i] = '0;
    end
  end

  gemm_core #(.TILE_N(TILE_N), .MAX_K(MAX_K), .MAX_N(MAX_N)) u_core (
    .clk(clk), .rst_n(rst_n), .do_start(do_compute_start), .do_step(do_compute_step), .cfg_k(cfg_k), .lane_active(lane_active),
    .a_elem(a_elem), .b_vec(b_vec), .tile_done(compute_tile_done), .lane_acc(lane_acc)
  );

  postproc_relu_bias #(.TILE_N(TILE_N)) u_post (
    .bias_enable(cfg_bias_enable), .lane_active(lane_active), .idx_n_base(idx_n_base), .cfg_n(cfg_n), .lane_acc(lane_acc), .bias_mem(buf_bias), .lane_out(lane_post)
  );

  output_streamer #(.TILE_N(TILE_N), .MAX_N(MAX_N)) u_out (
    .clk(clk), .rst_n(rst_n), .do_start(do_emit_start), .lane_active(lane_active), .lane_data(lane_post),
    .out_valid(out_valid), .out_ready(out_ready), .out_data(out_data), .emit_busy(emit_busy), .emit_done(emit_done)
  );

  always_ff @(posedge clk) begin
    if (!rst_n) status_done <= 1'b0;
    else        status_done <= do_done_pulse;
  end
endmodule"},{"path":"npu_control_fsm.sv","module":"npu_control_fsm","purpose":"Command decode, legality checking, FSM/state progression, counters, control strobes, sticky error.","content":"module npu_control_fsm #(
  parameter int MAX_M = 64,
  parameter int MAX_N = 64,
  parameter int MAX_K = 64,
  parameter int TILE_N = 8
)(
  input  logic clk,
  input  logic rst_n,
  input  logic cmd_valid,
  output logic cmd_ready,
  input  logic [95:0] cmd_data,
  input  logic load_a_done,
  input  logic load_b_done,
  input  logic load_bias_done,
  input  logic compute_tile_done,
  input  logic emit_done,
  output logic [15:0] cfg_m,
  output logic [15:0] cfg_n,
  output logic [15:0] cfg_k,
  output logic        cfg_bias_enable,
  output logic st_load_a,
  output logic st_load_b,
  output logic st_load_bias,
  output logic st_compute,
  output logic st_emit,
  output logic do_compute_start,
  output logic do_compute_step,
  output logic do_emit_start,
  output logic do_done_pulse,
  output logic [$clog2(MAX_M)-1:0] idx_m,
  output logic [$clog2(MAX_N)-1:0] idx_n_base,
  output logic [$clog2(MAX_K)-1:0] idx_k,
  output logic [TILE_N-1:0] lane_active,
  output logic status_error
);
  typedef enum logic [2:0] {IDLE, LOAD_A, LOAD_B, LOAD_BIAS, COMPUTE, EMIT, DONE} state_t;
  state_t state;
  logic [15:0] n_tiles;
  logic [15:0] t_idx;

  always_comb begin
    st_load_a = (state==LOAD_A); st_load_b = (state==LOAD_B); st_load_bias = (state==LOAD_BIAS);
    st_compute = (state==COMPUTE); st_emit = (state==EMIT);
    cmd_ready = (state==IDLE) && !status_error;
    do_compute_step = (state==COMPUTE);
  end

  always_comb begin
    for (int i=0;i<TILE_N;i++) begin
      if ((idx_n_base + i) < cfg_n) lane_active[i]=1'b1; else lane_active[i]=1'b0;
    end
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      state <= IDLE; cfg_m<=0; cfg_n<=0; cfg_k<=0; cfg_bias_enable<=0; status_error<=0;
      idx_m<=0; idx_n_base<=0; idx_k<=0; t_idx<=0; n_tiles<=0;
      do_compute_start<=0; do_emit_start<=0; do_done_pulse<=0;
    end else begin
      do_compute_start<=0; do_emit_start<=0; do_done_pulse<=0;
      case (state)
        IDLE: begin
          if (cmd_valid && cmd_ready) begin
            cfg_m <= cmd_data[15:0]; cfg_n <= cmd_data[31:16]; cfg_k <= cmd_data[47:32]; cfg_bias_enable <= cmd_data[48];
            if ((cmd_data[15:0]<1)||(cmd_data[15:0]>MAX_M)||(cmd_data[31:16]<1)||(cmd_data[31:16]>MAX_N)||(cmd_data[47:32]<1)||(cmd_data[47:32]>MAX_K)||(cmd_data[95:49]!=0)) begin
              status_error <= 1'b1;
            end else begin
              state <= LOAD_A;
              n_tiles <= (cmd_data[31:16] + TILE_N - 1)/TILE_N;
            end
          end
        end
        LOAD_A: if (load_a_done) state <= LOAD_B;
        LOAD_B: if (load_b_done) state <= cfg_bias_enable ? LOAD_BIAS : COMPUTE;
        LOAD_BIAS: if (load_bias_done) state <= COMPUTE;
        COMPUTE: begin
          if (idx_k==0) do_compute_start <= 1'b1;
          if (compute_tile_done) begin
            state <= EMIT;
            do_emit_start <= 1'b1;
          end
        end
        EMIT: if (emit_done) begin
          if (t_idx + 1 < n_tiles) begin
            t_idx <= t_idx + 1;
            idx_n_base <= (t_idx + 1)*TILE_N;
            idx_k <= 0;
            state <= COMPUTE;
          end else if (idx_m + 1 < cfg_m) begin
            idx_m <= idx_m + 1;
            t_idx <= 0;
            idx_n_base <= 0;
            idx_k <= 0;
            state <= COMPUTE;
          end else begin
            state <= DONE;
          end
        end
        DONE: begin
          do_done_pulse <= 1'b1;
          state <= IDLE;
          idx_m<=0; idx_n_base<=0; idx_k<=0; t_idx<=0;
        end
      endcase
      if (state==COMPUTE && !compute_tile_done) idx_k <= idx_k + 1;
    end
  end
endmodule"},{"path":"input_loader.sv","module":"input_loader","purpose":"Ready/valid-driven A/B/bias loading with counters and write controls.","content":"module input_loader #(
  parameter int MAX_M = 64,
  parameter int MAX_N = 64,
  parameter int MAX_K = 64
)(
  input  logic clk,
  input  logic rst_n,
  input  logic st_load_a,
  input  logic st_load_b,
  input  logic st_load_bias,
  input  logic bias_enable,
  input  logic [15:0] cfg_m,
  input  logic [15:0] cfg_n,
  input  logic [15:0] cfg_k,
  input  logic a_valid,
  output logic a_ready,
  input  logic signed [7:0] a_data,
  input  logic b_valid,
  output logic b_ready,
  input  logic signed [7:0] b_data,
  input  logic bias_valid,
  output logic bias_ready,
  input  logic signed [31:0] bias_data,
  output logic a_wr_en,
  output logic [$clog2(MAX_M*MAX_K)-1:0] a_wr_addr,
  output logic signed [7:0] a_wr_data,
  output logic b_wr_en,
  output logic [$clog2(MAX_K*MAX_N)-1:0] b_wr_addr,
  output logic signed [7:0] b_wr_data,
  output logic bias_wr_en,
  output logic [$clog2(MAX_N)-1:0] bias_wr_addr,
  output logic signed [31:0] bias_wr_data,
  output logic load_a_done,
  output logic load_b_done,
  output logic load_bias_done
);
  logic [31:0] cnt_a, cnt_b, cnt_bias;
  always_comb begin
    a_ready = st_load_a;
    b_ready = st_load_b;
    bias_ready = st_load_bias && bias_enable;
    a_wr_en = st_load_a && a_valid && a_ready;
    b_wr_en = st_load_b && b_valid && b_ready;
    bias_wr_en = st_load_bias && bias_enable && bias_valid && bias_ready;
    a_wr_addr = cnt_a[$clog2(MAX_M*MAX_K)-1:0];
    b_wr_addr = cnt_b[$clog2(MAX_K*MAX_N)-1:0];
    bias_wr_addr = cnt_bias[$clog2(MAX_N)-1:0];
    a_wr_data = a_data;
    b_wr_data = b_data;
    bias_wr_data = bias_data;
    load_a_done = (cnt_a == (cfg_m*cfg_k));
    load_b_done = (cnt_b == (cfg_k*cfg_n));
    load_bias_done = (!bias_enable) || (cnt_bias == cfg_n);
  end
  always_ff @(posedge clk) begin
    if (!rst_n) begin cnt_a<=0; cnt_b<=0; cnt_bias<=0; end
    else begin
      if (!st_load_a) cnt_a<=0; else if (a_wr_en) cnt_a<=cnt_a+1;
      if (!st_load_b) cnt_b<=0; else if (b_wr_en) cnt_b<=cnt_b+1;
      if (!st_load_bias) cnt_bias<=0; else if (bias_wr_en) cnt_bias<=cnt_bias+1;
    end
  end
endmodule"},{"path":"gemm_core.sv","module":"gemm_core","purpose":"TILE_N-lane signed int8 MAC accumulation across K into int32 lane accumulators.","content":"module gemm_core #(
  parameter int TILE_N = 8,
  parameter int MAX_K = 64,
  parameter int MAX_N = 64
)(
  input  logic clk,
  input  logic rst_n,
  input  logic do_start,
  input  logic do_step,
  input  logic [15:0] cfg_k,
  input  logic [TILE_N-1:0] lane_active,
  input  logic signed [7:0] a_elem,
  input  logic signed [7:0] b_vec [0:TILE_N-1],
  output logic tile_done,
  output logic signed [31:0] lane_acc [0:TILE_N-1]
);
  logic [15:0] k_count;
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      k_count <= 0;
      for (int i=0;i<TILE_N;i++) lane_acc[i] <= '0;
    end else begin
      if (do_start) begin
        k_count <= 0;
        for (int i=0;i<TILE_N;i++) lane_acc[i] <= '0;
      end else if (do_step) begin
        k_count <= k_count + 1;
        for (int i=0;i<TILE_N;i++) begin
          logic signed [15:0] p16;
          logic signed [31:0] p32;
          p16 = a_elem * b_vec[i];
          p32 = {{16{p16[15]}}, p16};
          if (lane_active[i]) lane_acc[i] <= lane_acc[i] + p32;
        end
      end
    end
  end
  always_comb tile_done = (do_step && (k_count + 1 >= cfg_k));
endmodule"},{"path":"postproc_relu_bias.sv","module":"postproc_relu_bias","purpose":"Combinational optional int32 bias add with wrap semantics and ReLU clamp.","content":"module postproc_relu_bias #(
  parameter int TILE_N = 8
)(
  input  logic bias_enable,
  input  logic [TILE_N-1:0] lane_active,
  input  logic [15:0] idx_n_base,
  input  logic [15:0] cfg_n,
  input  logic signed [31:0] lane_acc [0:TILE_N-1],
  input  logic signed [31:0] bias_mem [0:cfg_n-1],
  output logic signed [31:0] lane_out [0:TILE_N-1]
);
  always_comb begin
    for (int i=0;i<TILE_N;i++) begin
      logic signed [31:0] t;
      if (lane_active[i]) begin
        t = lane_acc[i] + (bias_enable ? bias_mem[idx_n_base+i] : 32'sd0);
        lane_out[i] = (t < 0) ? 32'sd0 : t;
      end else lane_out[i] = 32'sd0;
    end
  end
endmodule"},{"path":"output_streamer.sv","module":"output_streamer","purpose":"Serialize tile lane outputs with ready/valid backpressure and stable hold on stall.","content":"module output_streamer #(
  parameter int TILE_N = 8,
  parameter int MAX_N = 64
)(
  input  logic clk,
  input  logic rst_n,
  input  logic do_start,
  input  logic [TILE_N-1:0] lane_active,
  input  logic signed [31:0] lane_data [0:TILE_N-1],
  output logic out_valid,
  input  logic out_ready,
  output logic signed [31:0] out_data,
  output logic emit_busy,
  output logic emit_done
);
  logic [$clog2(TILE_N)-1:0] lane_idx;
  logic started;
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      out_valid<=0; out_data<=0; emit_busy<=0; emit_done<=0; lane_idx<=0; started<=0;
    end else begin
      emit_done <= 0;
      if (do_start) begin
        emit_busy <= 1;
        lane_idx <= 0;
        started <= 1;
      end
      if (emit_busy && started) begin
        if (lane_active[lane_idx]) begin
          out_valid <= 1;
          out_data <= lane_data[lane_idx];
          if (out_valid && out_ready) begin
            if (lane_idx == TILE_N-1) begin
              emit_busy <= 0;
              emit_done <= 1;
              out_valid <= 0;
              started <= 0;
            end
            lane_idx <= lane_idx + 1;
          end
        end else begin
          if (lane_idx == TILE_N-1) begin
            emit_busy <= 0;
            emit_done <= 1;
            out_valid <= 0;
            started <= 0;
          end else lane_idx <= lane_idx + 1;
        end
      end else begin
        out_valid <= 0;
      end
    end
  end
endmodule"}],"contract_checks":[{"requirement":"All manifest modules implemented exactly once as .sv files","satisfied":true,"evidence":"Generated 6 files matching module_manifest: top + 5 dependencies."},{"requirement":"Signed int8*int8 product sign-extended before int32 accumulation","satisfied":true,"evidence":"gemm_core uses signed [15:0] product and explicit sign-extension to signed [31:0] before add."},{"requirement":"FSM load-then-compute-emit sequencing without overlap","satisfied":true,"evidence":"npu_control_fsm transitions IDLE->LOAD_A->LOAD_B->LOAD_BIAS(optional)->COMPUTE->EMIT->DONE->IDLE."},{"requirement":"Ready/valid transfer semantics and output stall hold","satisfied":true,"evidence":"input_loader increments only on valid&&ready; output_streamer advances only on out_valid&&out_ready."},{"requirement":"Reset behavior synchronous active-low and required visible state","satisfied":true,"evidence":"All stateful modules use posedge clock with if(!rst_n) reset branches deasserting valids/flags and clearing counters/state."}],"changed_modules":["gemm_bias_relu_npu_top","npu_control_fsm","input_loader","gemm_core","postproc_relu_bias","output_streamer"],"architecture_conflict":null,"blocked_reason":"","architecture_changed":false,"interface_changed":false,"latency_changed":false,"known_risks":["postproc_relu_bias uses cfg_n in unpacked array port bound; some toolflows may require fixed MAX_N bound and explicit valid guard indexing.","Top-level loader write-data passthrough ports are unused; storage write uses direct input signals.","No explicit protocol error detection beyond command legality checks."],"regression_required":"FULL"}
